import { GoogleGenAI, Chat } from "@google/genai";
import type { ChatMessage, GroundingSource } from '../types';

if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable not set");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const planGenerationModel = 'gemini-2.5-pro';
const chatModel = 'gemini-2.5-flash';

let chat: Chat | null = null;

export const generateAutomationPlan = async (businessDescription: string): Promise<{ planText: string, sources: GroundingSource[] }> => {
    const prompt = `
Eres un experto consultor en automatización de clase mundial. Tu tarea es analizar una descripción de negocio y crear un plan de automatización detallado y accionable.

Basado en la siguiente descripción de negocio, crea un plan de automatización completo.

### Descripción del negocio:
"${businessDescription}"

### El plan debe incluir los siguientes cinco puntos, usando exactamente estos encabezados en formato markdown ###:

### 1. Análisis de Procesos Manuales
Identifica los procesos clave que son repetitivos, propensos a errores o que consumen mucho tiempo y que son candidatos ideales para la automatización. Sé específico y da ejemplos concretos relacionados con el negocio.

### 2. Diseño de Flujos de Agentes
Propón flujos de trabajo automatizados (agentes) para los procesos identificados. Describe paso a paso cómo operarían estos agentes y cómo interactuarían entre sí o con los humanos.

### 3. Stack Tecnológico Recomendado
Sugiere un conjunto de herramientas y tecnologías (software, plataformas, APIs) para construir e implementar las automatizaciones. Justifica tus elecciones basándote en la escalabilidad, coste y facilidad de uso para el negocio descrito. Utiliza información actualizada de la web.

### 4. Implementación Paso a Paso
Proporciona una hoja de ruta clara para la implementación, dividida en fases o hitos (ej. Fase 1: Automatización de la comunicación con clientes, Fase 2: Optimización de la gestión de proyectos, etc.).

### 5. ROI Estimado
Ofrece un análisis del retorno de la inversión esperado. Considera ahorros de costos (horas de trabajo, reducción de errores), aumento de eficiencia, y otros beneficios cualitativos como la mejora en la satisfacción del cliente. Proporciona una estimación cuantitativa si es posible (ej. "ahorro de X horas/semana").

Utiliza información actualizada y precisa de la web para el stack tecnológico y las mejores prácticas de implementación. Sé claro, conciso y profesional.
`;

    try {
        const response = await ai.models.generateContent({
            model: planGenerationModel,
            contents: prompt,
            config: {
                thinkingConfig: { thinkingBudget: 32768 },
                tools: [{ googleSearch: {} }],
            },
        });

        const planText = response.text;

        const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
        const sources: GroundingSource[] = groundingChunks
            .map((chunk: any) => ({
                uri: chunk.web?.uri || '',
                title: chunk.web?.title || 'Fuente sin título'
            }))
            .filter((source: GroundingSource) => source.uri);

        return { planText, sources };
    } catch (error) {
        console.error("Gemini API Error (generateAutomationPlan):", error);
        throw new Error("Failed to generate automation plan from Gemini API.");
    }
};


export const chatWithBot = async (history: ChatMessage[], newMessage: string): Promise<string> => {
    if (!chat) {
        chat = ai.chats.create({
            model: chatModel,
            history: history.map(msg => ({
                role: msg.role,
                parts: [{ text: msg.content }]
            })),
        });
    }

    try {
        const response = await chat.sendMessage({ message: newMessage });
        return response.text;
    } catch (error) {
        console.error("Gemini API Error (chatWithBot):", error);
        // Reset chat on error
        chat = null;
        throw new Error("Failed to get chat response from Gemini API.");
    }
};

export const resetChat = () => {
    chat = null;
};

import React, { useState, useRef, useEffect } from 'react';
import type { ChatMessage } from '../types';
import { chatWithBot, resetChat } from '../services/geminiService';
import { ChatBubbleIcon, CloseIcon, SendIcon, BotIcon, TrashIcon } from './icons';
import { LoadingSpinner } from './LoadingSpinner';

export const ChatBot: React.FC = () => {
    const [isOpen, setIsOpen] = useState(false);
    const [messages, setMessages] = useState<ChatMessage[]>(() => {
        const saved = localStorage.getItem('chat_history');
        if (saved) {
            try {
                return JSON.parse(saved);
            } catch (e) {
                console.error("Error parsing chat history", e);
            }
        }
        return [{ role: 'model', content: '¡Hola! Soy tu asistente de IA. ¿Cómo puedo ayudarte hoy?' }];
    });

    const [input, setInput] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    };

    useEffect(scrollToBottom, [messages, isOpen]);

    useEffect(() => {
        localStorage.setItem('chat_history', JSON.stringify(messages));
    }, [messages]);

    const handleSend = async () => {
        if (!input.trim() || isLoading) return;

        const userMessage: ChatMessage = { role: 'user', content: input };
        setMessages(prev => [...prev, userMessage]);
        setInput('');
        setIsLoading(true);

        try {
            const botResponse = await chatWithBot(messages, input);
            const modelMessage: ChatMessage = { role: 'model', content: botResponse };
            setMessages(prev => [...prev, modelMessage]);
        } catch (error) {
            const errorMessage: ChatMessage = { role: 'model', content: 'Lo siento, ocurrió un error. Por favor intenta de nuevo.' };
            setMessages(prev => [...prev, errorMessage]);
        } finally {
            setIsLoading(false);
        }
    };

    const handleClearChat = () => {
        const initialMsg: ChatMessage = { role: 'model', content: '¡Hola! Soy tu asistente de IA. ¿Cómo puedo ayudarte hoy?' };
        setMessages([initialMsg]);
        resetChat();
        localStorage.removeItem('chat_history');
    };

    const handleKeyPress = (e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.key === 'Enter') {
            handleSend();
        }
    }


    return (
        <>
            <button
                onClick={() => setIsOpen(!isOpen)}
                className={`fixed bottom-6 right-6 w-16 h-16 rounded-full bg-cyan-600 text-white shadow-lg hover:bg-cyan-500 transition-all transform hover:scale-110 flex items-center justify-center z-50 ${isOpen ? 'opacity-0 scale-0' : 'opacity-100 scale-100'}`}
                aria-label="Abrir chat"
            >
                <ChatBubbleIcon className="w-8 h-8" />
            </button>

            <div className={`fixed bottom-6 right-6 w-[calc(100%-3rem)] max-w-sm h-[70vh] max-h-[600px] bg-gray-800 rounded-2xl shadow-2xl flex flex-col transition-all duration-300 ease-in-out z-50 border border-gray-700 ${isOpen ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10 pointer-events-none'}`}>
                <header className="flex items-center justify-between p-4 border-b border-gray-700 bg-gray-800/70 backdrop-blur-sm rounded-t-2xl">
                    <h3 className="font-bold text-lg text-white">Asistente IA</h3>
                    <div className="flex items-center space-x-2">
                        <button 
                            onClick={handleClearChat} 
                            className="text-gray-400 hover:text-red-400 p-1 rounded-full hover:bg-gray-700/50 transition-colors"
                            title="Borrar historial"
                        >
                            <TrashIcon className="w-5 h-5" />
                        </button>
                        <button onClick={() => setIsOpen(false)} className="text-gray-400 hover:text-white p-1 rounded-full hover:bg-gray-700/50 transition-colors">
                            <CloseIcon className="w-6 h-6" />
                        </button>
                    </div>
                </header>

                <div className="flex-1 p-4 overflow-y-auto space-y-4">
                    {messages.map((msg, index) => (
                        <div key={index} className={`flex items-end gap-2 ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                           {msg.role === 'model' && <div className="w-8 h-8 rounded-full bg-cyan-500 flex items-center justify-center flex-shrink-0"><BotIcon className="w-5 h-5 text-white" /></div>}
                           <div className={`max-w-[80%] rounded-2xl px-4 py-2 ${msg.role === 'user' ? 'bg-cyan-700 text-white rounded-br-none' : 'bg-gray-700 text-gray-200 rounded-bl-none'}`}>
                                <p className="text-sm">{msg.content}</p>
                           </div>
                        </div>
                    ))}
                    {isLoading && (
                        <div className="flex items-end gap-2 justify-start">
                             <div className="w-8 h-8 rounded-full bg-cyan-500 flex items-center justify-center flex-shrink-0"><BotIcon className="w-5 h-5 text-white" /></div>
                             <div className="max-w-[80%] rounded-2xl px-4 py-2 bg-gray-700 text-gray-200 rounded-bl-none">
                                <LoadingSpinner />
                             </div>
                        </div>
                    )}
                    <div ref={messagesEndRef} />
                </div>

                <footer className="p-4 border-t border-gray-700">
                    <div className="flex items-center bg-gray-900 rounded-full border border-gray-700 focus-within:border-cyan-500 focus-within:ring-1 focus-within:ring-cyan-500 transition-all">
                        <input
                            type="text"
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            onKeyPress={handleKeyPress}
                            placeholder="Escribe un mensaje..."
                            className="flex-1 bg-transparent px-4 py-2 text-white placeholder-gray-500 focus:outline-none"
                            disabled={isLoading}
                        />
                        <button onClick={handleSend} disabled={!input.trim() || isLoading} className="p-2 text-cyan-400 hover:text-cyan-300 disabled:text-gray-600 disabled:cursor-not-allowed m-1">
                            <SendIcon className="w-6 h-6"/>
                        </button>
                    </div>
                </footer>
            </div>
        </>
    );
};

